{"path":"neuron_growth_ollama-glm-4.7-flash-latest_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Neural Network Simulation</title>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      background: #05070f;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      font-family: 'Courier New', monospace;
    }
    canvas {
      box-shadow: 0 0 40px rgba(0, 229, 255, 0.3), 0 0 80px rgba(16, 26, 58, 0.8);
    }
  </style>
</head>
<body>
  <canvas id="canvas" width="800" height="800"></canvas>
  <script>
    // === SETUP ===
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    // === STATE ===
    let neurons = [];
    let branches = [];
    let synapses = [];
    let pulses = [];
    let isPaused = false;
    let animationId;

    // === CONFIG ===
    const config = {
      // Growth
      neuronCount: 4,
      branchSpeed: 1,
      maxDepth: 8,
      splitChance: 0.35,
      curvature: 0.3,
      maxBranchLength: 150,
      // Synapses
      synapseThreshold: 35,
      synapseGlow: 15,
      // Pulses
      pulseSpeed: 5,
      pulseFrequency: 0.02,
      pulseBrightness: 1.0,
      // Visuals
      bgColor: '#05070f',
      branchColor: '#00e5ff',
      accentColor: '#d6ff00',
      synapseColor: '#ff2bd6',
      pulseColor: '#fff36a'
    };

    // === HELPERS ===
    function random(min, max) {
      return Math.random() * (max - min) + min;
    }

    function dist(x1, y1, x2, y2) {
      return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
    }

    // === NEURON GROWTH ===
    function growBranch(startX, startY, angle, depth, parentBranch) {
      const branch = {
        startX, startY,
        x: startX, y: startY,
        angle,
        depth,
        length: 0,
        maxLength: config.maxBranchLength * (0.5 + Math.random() * 0.5),
        thickness: depth < 3 ? 1.5 : 1.0,
        parent: parentBranch,
        children: [],
        path: [{x: startX, y: startY}],
        color: depth % 3 === 2 ? config.accentColor : config.branchColor
      };

      branches.push(branch);
      return branch;
    }

    function updateBranches() {
      if (isPaused) return;

      branches.forEach(branch => {
        if (branch.growing && branch.length < branch.maxLength) {
          branch.length += config.branchSpeed;
          branch.angle += random(-config.curvature, config.curvature) * 0.1;
          branch.x = branch.startX + Math.cos(branch.angle) * branch.length;
          branch.y = branch.startY + Math.sin(branch.angle) * branch.length;
          branch.path.push({x: branch.x, y: branch.y});

          // Split chance
          if (Math.random() < config.splitChance && branch.depth < config.maxDepth) {
            const splitAngle = branch.angle + random(-0.5, 0.5);
            const child = growBranch(branch.x, branch.y, splitAngle, branch.depth + 1, branch);
            branch.children.push(child);
          }
        }
      });

      // Detect synapses
      detectSynapses();

      // Remove finished branches
      branches = branches.filter(b => b.growing || b.children.length > 0);

      // Stop if no more growing
      const stillGrowing = branches.some(b => b.growing || b.children.some(c => c.growing));
      if (!stillGrowing && neurons.length > 0) {
        neurons.forEach(n => n.growing = false);
      }
    }

    function detectSynapses() {
      const tips = branches.filter(b => b.growing && b.children.length === 0);
      for (let i = 0; i < tips.length; i++) {
        for (let j = i + 1; j < tips.length; j++) {
          const d = dist(tips[i].x, tips[i].y, tips[j].x, tips[j].y);
          if (d < config.synapseThreshold) {
            const exists = synapses.some(s => 
              (s.b1 === tips[i] && s.b2 === tips[j]) || (s.b1 === tips[j] && s.b2 === tips[i])
            );
            if (!exists) {
              synapses.push({b1: tips[i], b2: tips[j], strength: 0});
            }
          }
        }
      }
    }

    // === PULSE ANIMATION ===
    function updatePulses() {
      if (isPaused) return;

      // Spawn new pulses
      if (Math.random() < config.pulseFrequency && synapses.length > 0) {
        const synapse = synapses[Math.floor(Math.random() * synapses.length)];
        pulses.push({
          synapse,
          progress: 0,
          speed: random(config.pulseSpeed * 0.8, config.pulseSpeed * 1.2)
        });
      }

      // Move pulses
      pulses.forEach(p => {
        p.progress += p.speed / 100;
      });

      // Remove finished pulses
      pulses = pulses.filter(p => p.progress < 1);
    }

    // === RENDERING ===
    function render() {
      ctx.fillStyle = config.bgColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Background glow
      ctx.fillStyle = '#101a3a';
      ctx.globalAlpha = 0.15;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.globalAlpha = 1;

      // Draw branches
      ctx.lineCap = 'round';
      branches.forEach(branch => {
        ctx.strokeStyle = branch.color;
        ctx.lineWidth = branch.thickness;
        ctx.shadowBlur = 10;
        ctx.shadowColor = branch.color;

        if (branch.path.length > 1) {
          ctx.beginPath();
          ctx.moveTo(branch.path[0].x, branch.path[0].y);
          for (let i = 1; i < branch.path.length; i++) {
            ctx.lineTo(branch.path[i].x, branch.path[i].y);
          }
          ctx.stroke();
        }
      });

      // Draw synapses
      synapses.forEach(s => {
        ctx.strokeStyle = config.synapseColor;
        ctx.lineWidth = 1.5;
        ctx.shadowBlur = config.synapseGlow;
        ctx.shadowColor = config.synapseColor;
        ctx.beginPath();
        ctx.moveTo(s.b1.x, s.b1.y);
        ctx.lineTo(s.b2.x, s.b2.y);
        ctx.stroke();
      });

      // Draw pulses
      pulses.forEach(p => {
        const progress = p.progress;
        const x = p.synapse.b1.x + (p.synapse.b2.x - p.synapse.b1.x) * progress;
        const y = p.synapse.b1.y + (p.synapse.b2.y - p.synapse.b1.y) * progress;

        ctx.fillStyle = config.pulseColor;
        ctx.shadowBlur = 20;
        ctx.shadowColor = config.pulseColor;
        ctx.globalAlpha = config.pulseBrightness;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      });

      // Vignette
      const gradient = ctx.createRadialGradient(
        400, 400, 300,
        400, 400, 450
      );
      gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
      gradient.addColorStop(1, 'rgba(0, 0, 0, 0.6)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Scanlines
      ctx.fillStyle = 'rgba(0, 229, 255, 0.03)';
      for (let y = 0; y < canvas.height; y += 4) {
        ctx.fillRect(0, y, canvas.width, 1);
      }
    }

    // === ANIMATION LOOP ===
    function animate() {
      updateBranches();
      updatePulses();
      render();
      animationId = requestAnimationFrame(animate);
    }

    // === INITIALIZATION ===
    function init() {
      neurons = [];
      branches = [];
      synapses = [];
      pulses = [];

      // Create seed neurons
      for (let i = 0; i < config.neuronCount; i++) {
        const angle = (i / config.neuronCount) * Math.PI * 2;
        const dist = random(50, 100);
        neurons.push({
          x: 400 + Math.cos(angle) * dist,
          y: 400 + Math.sin(angle) * dist,
          growing: true
        });
      }

      // Grow initial branches
      neurons.forEach(neuron => {
        for (let i = 0; i < 3; i++) {
          const angle = random(0, Math.PI * 2);
          growBranch(neuron.x, neuron.y, angle, 0, null);
        }
      });
    }

    // === GUI SETUP ===
    const gui = new dat.GUI({ autoPlace: false });
    document.body.appendChild(gui.domElement);
    gui.domElement.style.position = 'fixed';
    gui.domElement.style.top = '10px';
    gui.domElement.style.right = '10px';
    gui.domElement.style.zIndex = '1000';
    gui.domElement.style.opacity = '0.9';

    const growthFolder = gui.addFolder('Growth');
    growthFolder.add(config, 'neuronCount', 3, 6).step(1).onFinishChange(init);
    growthFolder.add(config, 'branchSpeed', 0.1, 3).step(0.1);
    growthFolder.add(config, 'maxDepth', 4, 12).step(1).onFinishChange(init);
    growthFolder.add(config, 'splitChance', 0.1, 0.8).step(0.05);
    growthFolder.add(config, 'curvature', 0, 1).step(0.1);
    growthFolder.add(config, 'maxBranchLength', 50, 250).step(10).onFinishChange(init);

    const synapseFolder = gui.addFolder('Synapses');
    synapseFolder.add(config, 'synapseThreshold', 20, 60).step(5).onFinishChange(detectSynapses);
    synapseFolder.add(config, 'synapseGlow', 0, 30).step(1);

    const pulseFolder = gui.addFolder('Pulses');
    pulseFolder.add(config, 'pulseSpeed', 1, 10).step(0.5);
    pulseFolder.add(config, 'pulseFrequency', 0, 0.1).step(0.005);
    pulseFolder.add(config, 'pulseBrightness', 0.2, 2).step(0.1);

    const visualsFolder = gui.addFolder('Visuals');
    visualsFolder.addColor(config, 'bgColor');
    visualsFolder.addColor(config, 'branchColor');
    visualsFolder.addColor(config, 'accentColor');
    visualsFolder.addColor(config, 'synapseColor');
    visualsFolder.addColor(config, 'pulseColor');
    visualsFolder.add({
      regenerate: () => init(),
      clear: () => { neurons = []; branches = []; synapses = []; pulses = []; },
      togglePause: () => { isPaused = !isPaused; }
    });

    // Start
    init();
    animate();
  </script>
</body>
</html>"}
